85	func (cm *CheckpointManager) Checkpoint(w io.Writer, timeout time.Duration) (*CheckpointMeta, int64, error) {
86		stats.Add(numCheckpointTotal, 1)
87	
88		if w == nil {
89			// Short-circuit if no writer provided, just checkpoint and truncate the database.
90			err := cm.db.CheckpointTruncateWithTimeout(timeout)
91			if err != nil {
92				return nil, 0, err
93			}
94			cm.nextFrameIdx = 0
95			cm.salt = nil
96			return &CheckpointMeta{Code: 0}, 0, nil
97		}
98	
99		/////////////////////////////////////////////////////////////////////////////////
100		// Write the compacted WAL pages to the provided writer.
101		walFD, err := os.Open(cm.walPath)
102		if err != nil {
103			return nil, 0, err
104		}
105		defer walFD.Close()
106	
107		walSzPre, err := fsutil.FileSize(cm.walPath)
108		if err != nil {
109			return nil, 0, err
110		}
111		if walSzPre == 0 {
112			// The WAL file is empty, so there is nothing to compact or checkpoint.
113			// This is an idempotent no-op: the WAL is already fully truncated.
114			stats.Get(preCompactWALSize).(*expvar.Int).Set(0)
115			cm.nextFrameIdx = 0
116			cm.salt = nil
117			return &CheckpointMeta{Code: 0}, 0, nil
118		}
119	
120		if cm.nextFrameIdx > 0 {
121			// The manager is telling us to start reading from other than the start. This
122			// means that the all frames were moved in the last checkpoint attempt, but the
123			// truncate itself failed. Before we start reading the WAL file from the given
124			// frame index, we need to check if the WAL was reset. If it was reset then
125			// SQLite started writing new frames from the beginning of the file, not appending
126			// at index nextFrameIdx.
127			//
128			// We can perform this check by comparing the salt values. If the salt values
129			// do not match, then we know that the WAL file has been reset, and we need to
130			// reset our state to start reading from the beginning of the WAL file again.
131			salt, err := readSaltAt(walFD)
132			if err != nil {
133				return nil, 0, fmt.Errorf("read WAL salt: %w", err)
134			}
135			if cm.salt == nil || *salt != *cm.salt {
136				cm.nextFrameIdx = 0
137				cm.salt = salt
138			}
139		}

